inline Variant& CurrentVariant() { static Variant v = Round; return v; }
inline const Palette& Colors() {
    switch (CurrentVariant()) {
        case Square: return PaletteSquare();
        case Round: return PaletteRound();
        case Blend: return PaletteBlend();
        case Paper: return PalettePaper();
    }
    return PaletteRound();
}
inline Fonts& LoadedFonts() { static Fonts f; return f; }

